 38→    private static final MemorySerializer<Long> LONG_DOC_ID_SERIALIZER = new MemorySerializer<>() {
 39→        @Override
 40→        public MemorySegment serialize(Long value) {
 41→            byte[] bytes = new byte[8];
 42→            long v = value;
 43→            for (int i = 7; i >= 0; i--) {
 44→                bytes[i] = (byte) (v & 0xFF);
 45→                v >>>= 8;
 46→            }
 47→            return MemorySegment.ofArray(bytes);
 48→        }
 49→
 50→        @Override
 51→        public Long deserialize(MemorySegment segment) {
 52→            byte[] bytes = segment.toArray(ValueLayout.JAVA_BYTE);
 53→            long v = 0L;
 54→            for (byte b : bytes)
 55→                v = (v << 8) | (b & 0xFFL);
 56→            return v;
 57→        }
