  30→/**
  31→ * Non-instantiable namespace class containing concrete {@link VectorIndex} implementations backed
  32→ * by an {@link LsmTree}.
  33→ *
  34→ * <ul>
  35→ * <li>{@link IvfFlat} — Inverted File with Flat re-scoring. Uses three key namespaces within one
  36→ * {@link LsmTree}: centroid coordinates {@code [0x00]}, posting-list entries {@code [0x01]}, and
  37→ * reverse-lookup entries {@code [0x02]}.</li>
  38→ * <li>{@link Hnsw} — Hierarchical Navigable Small World graph. Uses doc-id bytes as node keys,
  39→ * {@code [0xFE]} for the entry point, and {@code [0xFF][docId]} for soft-deletes.</li>
  40→ * </ul>
  41→ *
  42→ * <p>
  43→ * All similarity computations are accelerated with {@code FloatVector.SPECIES_PREFERRED} from
  44→ * {@code jdk.incubator.vector}, with a scalar tail loop for dimensions not covered by the SIMD
  45→ * width.
  46→ *
  47→ * <p>
  48→ * Obtain instances via {@link #ivfFlatBuilder()} and {@link #hnswBuilder()}.
  49→ */
  50→public final class LsmVectorIndex {
  51→
  52→    // Preferred SIMD species for float computation
  53→    private static final VectorSpecies<Float> SPECIES = FloatVector.SPECIES_PREFERRED;
  54→
  55→    private LsmVectorIndex() {
  56→        throw new UnsupportedOperationException("utility class");
  57→    }
  58→
  59→    // -----------------------------------------------------------------------
  60→    // Factory methods
  61→    // -----------------------------------------------------------------------
  62→
  63→    /** Returns a builder for an {@link IvfFlat} vector index backed by an {@link LsmTree}. */
  64→    public static <D> IvfFlat.Builder<D> ivfFlatBuilder() {
  65→        return new IvfFlat.Builder<>();
  66→    }
  67→
  68→    /** Returns a builder for an {@link Hnsw} vector index backed by an {@link LsmTree}. */
  69→    public static <D> Hnsw.Builder<D> hnswBuilder() {
  70→        return new Hnsw.Builder<>();
  71→    }
  72→
  73→    // -----------------------------------------------------------------------
  74→    // Float encoding helpers
  75→    // -----------------------------------------------------------------------
  76→
  77→    static byte[] encodeFloats(float[] floats) {
  78→        assert floats != null : "floats must not be null";
  79→        byte[] bytes = new byte[floats.length * 4];
  80→        for (int i = 0; i < floats.length; i++) {
  81→            int bits = Float.floatToRawIntBits(floats[i]);
  82→            bytes[i * 4] = (byte) (bits >>> 24);
  83→            bytes[i * 4 + 1] = (byte) (bits >>> 16);
  84→            bytes[i * 4 + 2] = (byte) (bits >>> 8);
  85→            bytes[i * 4 + 3] = (byte) bits;
  86→        }
  87→        return bytes;
  88→    }
  89→
  90→    static float[] decodeFloats(byte[] bytes, int dimensions) {
  91→        assert bytes != null : "bytes must not be null";
  92→        assert bytes.length == dimensions * 4 : "byte count mismatch";
  93→        float[] floats = new float[dimensions];
  94→        for (int i = 0; i < dimensions; i++) {
  95→            int bits = ((bytes[i * 4] & 0xFF) << 24) | ((bytes[i * 4 + 1] & 0xFF) << 16)
  96→                    | ((bytes[i * 4 + 2] & 0xFF) << 8) | (bytes[i * 4 + 3] & 0xFF);
  97→            floats[i] = Float.intBitsToFloat(bits);
  98→        }
  99→        return floats;
 100→    }
