 214→            this.similarityFunction = Objects.requireNonNull(fn,
 215→                    "similarityFunction must not be null");
 216→            return (B) this;
 217→        }
 218→
 219→        void validateBase() {
 220→            Objects.requireNonNull(lsmTree, "lsmTree must not be null");
 221→            Objects.requireNonNull(docIdSerializer, "docIdSerializer must not be null");
 222→            if (dimensions <= 0) {
 223→                throw new IllegalArgumentException("dimensions must be > 0");
 224→            }
 225→            Objects.requireNonNull(similarityFunction, "similarityFunction must not be null");
 226→        }
 227→    }
