 229→    // -----------------------------------------------------------------------
 230→    // IvfFlat implementation
 231→    // -----------------------------------------------------------------------
 232→
 233→    /**
 234→     * Inverted File Flat (IVF-Flat) vector index.
 235→     *
 236→     * <h2>Key namespaces within the backing {@link LsmTree}</h2>
 237→     *
 238→     * <pre>
 239→     *   [0x00][4-byte BE centroid_id]               → dim×4 bytes (centroid float coords)
 240→     *   [0x01][4-byte BE centroid_id][doc_id_bytes] → dim×4 bytes (vector float coords)
 241→     *   [0x02][doc_id_bytes]                        → 4-byte BE centroid_id (reverse lookup)
 242→     * </pre>
 243→     *
 244→     * <h2>Clustering strategy</h2> The first {@code numClusters} indexed vectors become centroids.
 245→     * Subsequent vectors are assigned to the nearest centroid (using the configured
 246→     * {@link SimilarityFunction}).
 247→     */
 248→    public static final class IvfFlat<D> implements VectorIndex.IvfFlat<D> {
 249→
 250→        // Key namespace prefix bytes
 251→        private static final byte CENTROID_PREFIX = 0x00;
 252→        private static final byte POSTING_PREFIX = 0x01;
 253→        private static final byte REVERSE_PREFIX = 0x02;
 254→
 255→        // Scan bounds: [CENTROID_PREFIX, POSTING_PREFIX) covers all centroid keys
 256→        private static final MemorySegment CENTROID_SCAN_START = MemorySegment
 257→                .ofArray(new byte[]{ CENTROID_PREFIX });
 258→        private static final MemorySegment CENTROID_SCAN_END = MemorySegment
 259→                .ofArray(new byte[]{ POSTING_PREFIX });
 260→
 261→        private final LsmTree lsmTree;
 262→        private final MemorySerializer<D> docIdSerializer;
 263→        private final int dimensions;
 264→        private final SimilarityFunction similarityFunction;
 265→        private final int numClusters;
 266→        private final int nprobe;
 267→
 268→        private IvfFlat(LsmTree lsmTree, MemorySerializer<D> docIdSerializer, int dimensions,
 269→                SimilarityFunction similarityFunction, int numClusters, int nprobe) {
 270→            assert lsmTree != null;
 271→            assert docIdSerializer != null;
 272→            assert dimensions > 0;
 273→            assert similarityFunction != null;
 274→            assert numClusters > 0;
 275→            assert nprobe > 0;
 276→            this.lsmTree = lsmTree;
 277→            this.docIdSerializer = docIdSerializer;
 278→            this.dimensions = dimensions;
 279→            this.similarityFunction = similarityFunction;
 280→            this.numClusters = numClusters;
 281→            this.nprobe = nprobe;
 282→        }
 283→
 284→        @Override
 285→        public void index(D docId, float[] vector) throws IOException {
 286→            Objects.requireNonNull(docId, "docId must not be null");
 287→            Objects.requireNonNull(vector, "vector must not be null");
 288→            if (vector.length != dimensions) {
 289→                throw new IllegalArgumentException(
 290→                        "vector.length=" + vector.length + " != dimensions=" + dimensions);
 291→            }
 292→
 293→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
 294→            byte[] vectorBytes = encodeFloats(vector);
 295→
 296→            int centroidId = assignCentroid(vector);
 297→
 298→            // Store posting: [0x01][centroid_id][docId] → vector
 299→            lsmTree.put(MemorySegment.ofArray(postingKey(centroidId, docIdBytes)),
 300→                    MemorySegment.ofArray(vectorBytes));
 301→
 302→            // Store reverse lookup: [0x02][docId] → centroid_id (4 bytes BE)
 303→            lsmTree.put(MemorySegment.ofArray(reverseKey(docIdBytes)),
 304→                    MemorySegment.ofArray(encodeCentroidId(centroidId)));
 305→        }
 306→
 307→        @Override
 308→        public void remove(D docId) throws IOException {
 309→            Objects.requireNonNull(docId, "docId must not be null");
 310→
 311→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
 312→            byte[] revKey = reverseKey(docIdBytes);
 313→
 314→            Optional<MemorySegment> revOpt = lsmTree.get(MemorySegment.ofArray(revKey));
 315→            if (revOpt.isEmpty())
 316→                return; // not indexed
 317→
 318→            int centroidId = decodeCentroidId(revOpt.get().toArray(ValueLayout.JAVA_BYTE), 0);
 319→
 320→            lsmTree.delete(MemorySegment.ofArray(postingKey(centroidId, docIdBytes)));
 321→            lsmTree.delete(MemorySegment.ofArray(revKey));
 322→        }
 323→
 324→        @Override
 325→        public List<VectorIndex.SearchResult<D>> search(float[] query, int topK)
 326→                throws IOException {
 327→            Objects.requireNonNull(query, "query must not be null");
 328→            if (query.length != dimensions) {
 329→                throw new IllegalArgumentException(
 330→                        "query.length=" + query.length + " != dimensions=" + dimensions);
 331→            }
 332→            if (topK <= 0)
 333→                throw new IllegalArgumentException("topK must be > 0");
 334→
 335→            // Load all centroids
 336→            List<float[]> centroidVecs = new ArrayList<>();
 337→            List<Integer> centroidIds = new ArrayList<>();
 338→            Iterator<Entry> centIt = lsmTree.scan(CENTROID_SCAN_START, CENTROID_SCAN_END);
 339→            while (centIt.hasNext()) {
 340→                Entry entry = centIt.next();
 341→                if (!(entry instanceof Entry.Put put))
 342→                    continue;
 343→                byte[] key = entry.key().toArray(ValueLayout.JAVA_BYTE);
 344→                if (key.length != 5 || key[0] != CENTROID_PREFIX)
 345→                    continue;
 346→                int cid = decodeCentroidId(key, 1);
 347→                float[] cVec = decodeFloats(put.value().toArray(ValueLayout.JAVA_BYTE), dimensions);
 348→                centroidVecs.add(cVec);
 349→                centroidIds.add(cid);
 350→            }
 351→
 352→            if (centroidVecs.isEmpty())
 353→                return List.of();
 354→
 355→            // Score centroids, pick top nprobe
 356→            int actualNprobe = Math.min(nprobe, centroidVecs.size());
 357→            int[] nearestCentroidIds = topNCentroids(query, centroidVecs, centroidIds,
 358→                    actualNprobe);
 359→
 360→            // Accumulate candidates from posting lists (min-heap to evict worst when over topK)
 361→            PriorityQueue<ScoredCandidate> heap = new PriorityQueue<>(
 362→                    Comparator.comparingDouble(ScoredCandidate::score)); // min at head for eviction
 363→
 364→            for (int cid : nearestCentroidIds) {
 365→                byte[] postStart = postingKey(cid, new byte[0]);
 366→                byte[] postEnd = postingEndKey(cid);
 367→
 368→                Iterator<Entry> postIt = lsmTree.scan(MemorySegment.ofArray(postStart),
 369→                        MemorySegment.ofArray(postEnd));
 370→
 371→                while (postIt.hasNext()) {
 372→                    Entry entry = postIt.next();
 373→                    if (!(entry instanceof Entry.Put put))
 374→                        continue; // skip tombstones
 375→
 376→                    byte[] key = entry.key().toArray(ValueLayout.JAVA_BYTE);
 377→                    if (key.length <= 5 || key[0] != POSTING_PREFIX)
 378→                        continue;
 379→
 380→                    byte[] docIdBytes = Arrays.copyOfRange(key, 5, key.length);
 381→                    float[] vec = decodeFloats(put.value().toArray(ValueLayout.JAVA_BYTE),
 382→                            dimensions);
 383→                    float s = score(query, vec, similarityFunction);
 384→
 385→                    heap.add(new ScoredCandidate(docIdBytes, s));
 386→                    if (heap.size() > topK)
 387→                        heap.poll(); // evict worst
 388→                }
 389→            }
 390→
 391→            // Drain heap in descending order
 392→            List<ScoredCandidate> sorted = new ArrayList<>(heap);
 393→            sorted.sort((a, b) -> Float.compare(b.score(), a.score()));
 394→
 395→            List<VectorIndex.SearchResult<D>> results = new ArrayList<>(sorted.size());
 396→            for (ScoredCandidate c : sorted) {
 397→                D id = docIdSerializer.deserialize(MemorySegment.ofArray(c.docIdBytes()));
 398→                results.add(new VectorIndex.SearchResult<>(id, c.score()));
 399→            }
 400→            return results;
 401→        }
 402→
 403→        @Override
 404→        public void close() throws IOException {
 405→            lsmTree.close();
 406→        }
 407→
 408→        // --- Key construction helpers ---
 409→
 410→        private static byte[] centroidKey(int centroidId) {
 411→            return new byte[]{ CENTROID_PREFIX, (byte) (centroidId >>> 24),
 412→                    (byte) (centroidId >>> 16), (byte) (centroidId >>> 8), (byte) centroidId };
 413→        }
 414→
 415→        private static byte[] postingKey(int centroidId, byte[] docIdBytes) {
 416→            byte[] key = new byte[5 + docIdBytes.length];
 417→            key[0] = POSTING_PREFIX;
 418→            key[1] = (byte) (centroidId >>> 24);
 419→            key[2] = (byte) (centroidId >>> 16);
 420→            key[3] = (byte) (centroidId >>> 8);
 421→            key[4] = (byte) centroidId;
 422→            System.arraycopy(docIdBytes, 0, key, 5, docIdBytes.length);
 423→            return key;
 424→        }
 425→
 426→        private static byte[] postingEndKey(int centroidId) {
 427→            long next = (centroidId & 0xFFFFFFFFL) + 1L;
 428→            if (next > 0xFFFFFFFFL) {
 429→                return new byte[]{ REVERSE_PREFIX }; // overflow → next prefix byte
 430→            }
 431→            return new byte[]{ POSTING_PREFIX, (byte) (next >>> 24), (byte) (next >>> 16),
 432→                    (byte) (next >>> 8), (byte) next };
 433→        }
 434→
 435→        private static byte[] reverseKey(byte[] docIdBytes) {
 436→            byte[] key = new byte[1 + docIdBytes.length];
 437→            key[0] = REVERSE_PREFIX;
 438→            System.arraycopy(docIdBytes, 0, key, 1, docIdBytes.length);
 439→            return key;
 440→        }
 441→
 442→        private static byte[] encodeCentroidId(int centroidId) {
 443→            return new byte[]{ (byte) (centroidId >>> 24), (byte) (centroidId >>> 16),
 444→                    (byte) (centroidId >>> 8), (byte) centroidId };
 445→        }
 446→
 447→        private static int decodeCentroidId(byte[] bytes, int offset) {
 448→            return ((bytes[offset] & 0xFF) << 24) | ((bytes[offset + 1] & 0xFF) << 16)
 449→                    | ((bytes[offset + 2] & 0xFF) << 8) | (bytes[offset + 3] & 0xFF);
 450→        }
 451→
 452→        // --- Centroid assignment ---
 453→
 454→        /**
 455→         * Returns the centroid ID to assign to a new vector. Creates a new centroid if fewer than
 456→         * {@code numClusters} centroids exist; otherwise assigns to the most similar existing one.
 457→         */
 458→        private int assignCentroid(float[] vector) throws IOException {
 459→            List<float[]> centroids = new ArrayList<>();
 460→            List<Integer> centroidIdList = new ArrayList<>();
 461→
 462→            Iterator<Entry> it = lsmTree.scan(CENTROID_SCAN_START, CENTROID_SCAN_END);
 463→            while (it.hasNext()) {
 464→                Entry entry = it.next();
 465→                if (!(entry instanceof Entry.Put put))
 466→                    continue;
 467→                byte[] key = entry.key().toArray(ValueLayout.JAVA_BYTE);
 468→                if (key.length != 5 || key[0] != CENTROID_PREFIX)
 469→                    continue;
 470→                int cid = decodeCentroidId(key, 1);
 471→                float[] cVec = decodeFloats(put.value().toArray(ValueLayout.JAVA_BYTE), dimensions);
 472→                centroids.add(cVec);
 473→                centroidIdList.add(cid);
 474→            }
 475→
 476→            if (centroids.size() < numClusters) {
 477→                int newCid = centroids.size(); // sequential 0-based centroid IDs
 478→                lsmTree.put(MemorySegment.ofArray(centroidKey(newCid)),
 479→                        MemorySegment.ofArray(encodeFloats(vector)));
 480→                return newCid;
 481→            }
 482→
 483→            return nearestCentroid(vector, centroids, centroidIdList);
 484→        }
 485→
 486→        private int nearestCentroid(float[] vector, List<float[]> centroids, List<Integer> ids) {
 487→            int best = ids.get(0);
 488→            float bestScore = score(vector, centroids.get(0), similarityFunction);
 489→            for (int i = 1; i < centroids.size(); i++) {
 490→                float s = score(vector, centroids.get(i), similarityFunction);
 491→                if (s > bestScore) {
 492→                    bestScore = s;
 493→                    best = ids.get(i);
 494→                }
 495→            }
 496→            return best;
 497→        }
 498→
 499→        private int[] topNCentroids(float[] query, List<float[]> centroids, List<Integer> ids,
 500→                int n) {
 501→            float[] scores = new float[centroids.size()];
 502→            for (int i = 0; i < centroids.size(); i++) {
 503→                scores[i] = score(query, centroids.get(i), similarityFunction);
 504→            }
 505→            Integer[] indices = new Integer[centroids.size()];
 506→            for (int i = 0; i < indices.length; i++)
 507→                indices[i] = i;
 508→            Arrays.sort(indices, (a, b) -> Float.compare(scores[b], scores[a])); // descending
 509→
 510→            int[] result = new int[n];
 511→            for (int i = 0; i < n; i++)
 512→                result[i] = ids.get(indices[i]);
 513→            return result;
 514→        }
