 548→    // -----------------------------------------------------------------------
 549→    // Hnsw implementation
 550→    // -----------------------------------------------------------------------
 551→
 552→    /**
 553→     * Hierarchical Navigable Small World (HNSW) graph vector index.
 554→     *
 555→     * <h2>Key namespaces within the backing {@link LsmTree}</h2>
 556→     *
 557→     * <pre>
 558→     *   [doc_id_bytes]          → node value (see below) — node data
 559→     *   [0xFE]                  → [4-byte BE max_layer][doc_id_bytes] — entry point
 560→     *   [0xFF][doc_id_bytes]    → empty segment — soft-delete tombstone
 561→     * </pre>
 562→     *
 563→     * <h2>Node value encoding</h2>
 564→     *
 565→     * <pre>
 566→     *   [4-byte BE docIdBytesLen]
 567→     *   [4-byte BE layerCount]
 568→     *   for each layer l = 0..layerCount-1:
 569→     *     [4-byte BE neighborCount_l]
 570→     *     [neighborCount_l × docIdBytesLen bytes]
 571→     *   [dim × 4 bytes] — big-endian IEEE-754 float vector
 572→     * </pre>
 573→     *
 574→     * <h2>Soft-delete</h2> {@link #remove} writes a soft-delete key {@code [0xFF][docId]}. During
 575→     * search, soft-deleted nodes are skipped in result collection.
 576→     */
 577→    public static final class Hnsw<D> implements VectorIndex.Hnsw<D> {
 578→
 579→        private static final byte[] ENTRY_POINT_KEY = new byte[]{ (byte) 0xFE };
 580→        private static final byte SOFT_DELETE_PREFIX = (byte) 0xFF;
 581→
 582→        private final LsmTree lsmTree;
 583→        private final MemorySerializer<D> docIdSerializer;
 584→        private final int dimensions;
 585→        private final SimilarityFunction similarityFunction;
 586→        private final int maxConnections;
 587→        private final int efConstruction;
 588→        private final int efSearch;
 589→        private final Random random = new Random();
 590→
 591→        private Hnsw(LsmTree lsmTree, MemorySerializer<D> docIdSerializer, int dimensions,
 592→                SimilarityFunction similarityFunction, int maxConnections, int efConstruction,
 593→                int efSearch) {
 594→            assert lsmTree != null;
 595→            assert docIdSerializer != null;
 596→            assert dimensions > 0;
 597→            assert similarityFunction != null;
 598→            assert maxConnections > 0;
 599→            assert efConstruction > 0;
 600→            assert efSearch > 0;
 601→            this.lsmTree = lsmTree;
 602→            this.docIdSerializer = docIdSerializer;
 603→            this.dimensions = dimensions;
 604→            this.similarityFunction = similarityFunction;
 605→            this.maxConnections = maxConnections;
 606→            this.efConstruction = efConstruction;
 607→            this.efSearch = efSearch;
 608→        }
 609→
 610→        @Override
 611→        public void index(D docId, float[] vector) throws IOException {
 612→            Objects.requireNonNull(docId, "docId must not be null");
 613→            Objects.requireNonNull(vector, "vector must not be null");
 614→            if (vector.length != dimensions) {
 615→                throw new IllegalArgumentException(
 616→                        "vector.length=" + vector.length + " != dimensions=" + dimensions);
 617→            }
 618→
 619→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
 620→            int newLevel = randomLevel();
 621→
 622→            EntryPoint ep = readEntryPoint();
 623→
 624→            if (ep == null) {
 625→                // First node: create empty layer list and set as entry point
 626→                List<List<byte[]>> layers = new ArrayList<>();
 627→                for (int l = 0; l <= newLevel; l++)
 628→                    layers.add(new ArrayList<>());
 629→                lsmTree.put(MemorySegment.ofArray(docIdBytes),
 630→                        MemorySegment.ofArray(encodeNode(docIdBytes, layers, vector)));
 631→                lsmTree.put(MemorySegment.ofArray(ENTRY_POINT_KEY),
 632→                        MemorySegment.ofArray(encodeEntryPoint(docIdBytes, newLevel)));
 633→                return;
 634→            }
 635→
 636→            int maxLayer = ep.maxLayer();
 637→            byte[] currentEp = ep.docIdBytes();
 638→
 639→            // Phase 1: traverse from maxLayer down to newLevel+1, greedy (ef=1)
 640→            for (int lc = maxLayer; lc > newLevel; lc--) {
 641→                currentEp = greedySearch1(currentEp, vector, lc);
 642→            }
 643→
 644→            // Phase 2: from min(newLevel, maxLayer) down to 0, collect neighbors
 645→            int startLevel = Math.min(newLevel, maxLayer);
 646→            List<List<byte[]>> newNodeLayers = new ArrayList<>();
 647→            for (int l = 0; l <= newLevel; l++)
 648→                newNodeLayers.add(new ArrayList<>());
 649→
 650→            for (int lc = startLevel; lc >= 0; lc--) {
 651→                List<ScoredCandidate> candidates = searchLayer(currentEp, vector, efConstruction,
 652→                        lc);
 653→                List<byte[]> selectedNeighbors = selectNeighbors(candidates, maxConnections);
 654→                newNodeLayers.set(lc, selectedNeighbors);
 655→
 656→                // Update currentEp for next (lower) layer: best candidate in this layer
 657→                if (!candidates.isEmpty()) {
 658→                    ScoredCandidate best = candidates.stream()
 659→                            .max(Comparator.comparingDouble(ScoredCandidate::score)).orElseThrow();
 660→                    currentEp = best.docIdBytes();
 661→                }
 662→
 663→                // Bidirectional neighbor updates
 664→                for (byte[] nbId : selectedNeighbors) {
 665→                    Optional<MemorySegment> nbOpt = lsmTree.get(MemorySegment.ofArray(nbId));
 666→                    if (nbOpt.isEmpty())
 667→                        continue;
 668→
 669→                    DecodedNode nbNode = decodeNode(nbOpt.get().toArray(ValueLayout.JAVA_BYTE));
 670→                    if (lc >= nbNode.layerNeighbors().size())
 671→                        continue;
 672→
 673→                    List<List<byte[]>> updatedLayers = new ArrayList<>(nbNode.layerNeighbors());
 674→                    List<byte[]> updatedNbrs = new ArrayList<>(updatedLayers.get(lc));
 675→                    updatedNbrs.add(docIdBytes);
 676→
 677→                    if (updatedNbrs.size() > maxConnections) {
 678→                        updatedNbrs = trimToM(nbNode.vector(), updatedNbrs, maxConnections);
 679→                    }
 680→
 681→                    updatedLayers.set(lc, updatedNbrs);
 682→                    lsmTree.put(MemorySegment.ofArray(nbId), MemorySegment
 683→                            .ofArray(encodeNode(nbId, updatedLayers, nbNode.vector())));
 684→                }
 685→            }
 686→
 687→            // Write new node
 688→            lsmTree.put(MemorySegment.ofArray(docIdBytes),
 689→                    MemorySegment.ofArray(encodeNode(docIdBytes, newNodeLayers, vector)));
 690→
 691→            // Promote entry point if this node has a higher level
 692→            if (newLevel > maxLayer) {
 693→                lsmTree.put(MemorySegment.ofArray(ENTRY_POINT_KEY),
 694→                        MemorySegment.ofArray(encodeEntryPoint(docIdBytes, newLevel)));
 695→            }
 696→        }
 697→
 698→        @Override
 699→        public void remove(D docId) throws IOException {
 700→            Objects.requireNonNull(docId, "docId must not be null");
 701→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
 702→            // Soft delete: write tombstone at [0xFF][docId]
 703→            lsmTree.put(MemorySegment.ofArray(softDeleteKey(docIdBytes)), MemorySegment.NULL);
 704→        }
 705→
 706→        @Override
 707→        public List<VectorIndex.SearchResult<D>> search(float[] query, int topK)
 708→                throws IOException {
 709→            Objects.requireNonNull(query, "query must not be null");
 710→            if (query.length != dimensions) {
 711→                throw new IllegalArgumentException(
 712→                        "query.length=" + query.length + " != dimensions=" + dimensions);
 713→            }
 714→            if (topK <= 0)
 715→                throw new IllegalArgumentException("topK must be > 0");
 716→
 717→            EntryPoint ep = readEntryPoint();
 718→            if (ep == null)
 719→                return List.of();
 720→
 721→            // Optional prefetch hint for the entry point
 722→            if (lsmTree instanceof PrefetchHint ph) {
 723→                ph.prefetch(List.of(MemorySegment.ofArray(ep.docIdBytes())));
 724→            }
 725→
 726→            byte[] currentEp = ep.docIdBytes();
 727→
 728→            // Phase 1: from maxLayer down to 1, greedy
 729→            for (int lc = ep.maxLayer(); lc > 0; lc--) {
 730→                currentEp = greedySearch1(currentEp, query, lc);
 731→            }
 732→
 733→            // Phase 2: layer 0 with efSearch
 734→            List<ScoredCandidate> candidates = searchLayer(currentEp, query, efSearch, 0);
 735→
 736→            // Sort descending, filter soft-deleted, take topK
 737→            candidates.sort((a, b) -> Float.compare(b.score(), a.score()));
 738→
 739→            List<VectorIndex.SearchResult<D>> results = new ArrayList<>();
 740→            for (ScoredCandidate c : candidates) {
 741→                if (results.size() >= topK)
 742→                    break;
 743→                if (isSoftDeleted(c.docIdBytes()))
 744→                    continue;
 745→                D id = docIdSerializer.deserialize(MemorySegment.ofArray(c.docIdBytes()));
 746→                results.add(new VectorIndex.SearchResult<>(id, c.score()));
 747→            }
 748→            return results;
 749→        }
 750→
 751→        @Override
 752→        public void close() throws IOException {
 753→            lsmTree.close();
 754→        }
 755→
 756→        // --- HNSW helpers ---
 757→
 758→        private int randomLevel() {
 759→            // Floor(-ln(U[0,1]) / ln(maxConnections)) — standard HNSW level assignment
 760→            double mL = 1.0 / Math.log(maxConnections);
 761→            int level = (int) (-Math.log(Math.max(1e-10, random.nextDouble())) * mL);
 762→            return Math.min(level, 16); // cap to prevent degenerate cases
 763→        }
 764→
 765→        private record EntryPoint(byte[] docIdBytes, int maxLayer) {
 766→        }
 767→
 768→        private EntryPoint readEntryPoint() throws IOException {
 769→            Optional<MemorySegment> opt = lsmTree.get(MemorySegment.ofArray(ENTRY_POINT_KEY));
 770→            if (opt.isEmpty())
 771→                return null;
 772→            byte[] value = opt.get().toArray(ValueLayout.JAVA_BYTE);
 773→            int maxLayer = readInt(value, 0);
 774→            byte[] docIdBytes = Arrays.copyOfRange(value, 4, value.length);
 775→            return new EntryPoint(docIdBytes, maxLayer);
 776→        }
 777→
 778→        private static byte[] encodeEntryPoint(byte[] docIdBytes, int maxLayer) {
 779→            byte[] value = new byte[4 + docIdBytes.length];
 780→            writeInt(value, 0, maxLayer);
 781→            System.arraycopy(docIdBytes, 0, value, 4, docIdBytes.length);
 782→            return value;
 783→        }
 784→
 785→        /**
 786→         * Greedily finds the single nearest node to {@code query} at {@code layer}, starting from
 787→         * {@code entryDocId}. Returns the docId of the nearest found node.
 788→         */
 789→        private byte[] greedySearch1(byte[] entryDocId, float[] query, int layer)
 790→                throws IOException {
 791→            byte[] currentId = entryDocId;
 792→            float currentScore = scoreNode(currentId, query);
 793→
 794→            boolean improved = true;
 795→            while (improved) {
 796→                improved = false;
 797→                for (byte[] nbId : getNodeNeighbors(currentId, layer)) {
 798→                    float s = scoreNode(nbId, query);
 799→                    if (s > currentScore) {
 800→                        currentScore = s;
 801→                        currentId = nbId;
 802→                        improved = true;
 803→                    }
 804→                }
 805→            }
 806→            return currentId;
 807→        }
 808→
 809→        /**
 810→         * Collects up to {@code ef} best candidates at {@code layer} starting from
 811→         * {@code entryDocId}, using a best-first search with bounded candidate set.
 812→         */
 813→        private List<ScoredCandidate> searchLayer(byte[] entryDocId, float[] query, int ef,
 814→                int layer) throws IOException {
 815→            Set<ByteBuffer> visited = new HashSet<>();
 816→            visited.add(ByteBuffer.wrap(entryDocId));
 817→
 818→            float entryScore = scoreNode(entryDocId, query);
 819→
 820→            // Expansion frontier: max-heap by score (expand best first)
 821→            PriorityQueue<ScoredCandidate> frontier = new PriorityQueue<>(
 822→                    (a, b) -> Float.compare(b.score(), a.score()));
 823→            // Result set: min-heap by score (evict worst when over ef)
 824→            PriorityQueue<ScoredCandidate> results = new PriorityQueue<>(
 825→                    Comparator.comparingDouble(ScoredCandidate::score));
 826→
 827→            ScoredCandidate entry = new ScoredCandidate(entryDocId, entryScore);
 828→            frontier.add(entry);
 829→            results.add(entry);
 830→
 831→            while (!frontier.isEmpty()) {
 832→                ScoredCandidate best = frontier.poll();
 833→                float worstResult = results.isEmpty() ? Float.NEGATIVE_INFINITY
 834→                        : results.peek().score();
 835→
 836→                // No candidate can improve results
 837→                if (best.score() < worstResult && results.size() >= ef)
 838→                    break;
 839→
 840→                for (byte[] nbId : getNodeNeighbors(best.docIdBytes(), layer)) {
 841→                    ByteBuffer nbBuf = ByteBuffer.wrap(nbId);
 842→                    if (!visited.add(nbBuf))
 843→                        continue; // already visited
 844→
 845→                    float nbScore = scoreNode(nbId, query);
 846→                    float currentWorst = results.isEmpty() ? Float.NEGATIVE_INFINITY
 847→                            : results.peek().score();
 848→
 849→                    if (results.size() < ef || nbScore > currentWorst) {
 850→                        ScoredCandidate nb = new ScoredCandidate(nbId, nbScore);
 851→                        frontier.add(nb);
 852→                        results.add(nb);
 853→                        if (results.size() > ef)
 854→                            results.poll();
 855→                    }
 856→                }
 857→            }
 858→
 859→            return new ArrayList<>(results);
 860→        }
 861→
 862→        private List<byte[]> selectNeighbors(List<ScoredCandidate> candidates, int maxM) {
 863→            return candidates.stream().sorted((a, b) -> Float.compare(b.score(), a.score()))
 864→                    .limit(maxM).map(ScoredCandidate::docIdBytes).collect(Collectors.toList());
 865→        }
 866→
 867→        /**
 868→         * Trims {@code neighbors} to at most {@code maxM}, keeping the {@code maxM} most similar to
 869→         * {@code centerVec} according to the configured {@link SimilarityFunction}.
 870→         */
 871→        private List<byte[]> trimToM(float[] centerVec, List<byte[]> neighbors, int maxM)
 872→                throws IOException {
 873→            List<ScoredCandidate> scored = new ArrayList<>();
 874→            for (byte[] nbId : neighbors) {
 875→                Optional<MemorySegment> nbOpt = lsmTree.get(MemorySegment.ofArray(nbId));
 876→                if (nbOpt.isEmpty())
 877→                    continue;
 878→                DecodedNode nbNode = decodeNode(nbOpt.get().toArray(ValueLayout.JAVA_BYTE));
 879→                float s = score(centerVec, nbNode.vector(), similarityFunction);
 880→                scored.add(new ScoredCandidate(nbId, s));
 881→            }
 882→            return selectNeighbors(scored, maxM);
 883→        }
 884→
 885→        private float scoreNode(byte[] docIdBytes, float[] query) throws IOException {
 886→            Optional<MemorySegment> opt = lsmTree.get(MemorySegment.ofArray(docIdBytes));
 887→            if (opt.isEmpty())
 888→                return Float.NEGATIVE_INFINITY;
 889→            DecodedNode node = decodeNode(opt.get().toArray(ValueLayout.JAVA_BYTE));
 890→            return score(query, node.vector(), similarityFunction);
 891→        }
 892→
 893→        private List<byte[]> getNodeNeighbors(byte[] docIdBytes, int layer) throws IOException {
 894→            Optional<MemorySegment> opt = lsmTree.get(MemorySegment.ofArray(docIdBytes));
 895→            if (opt.isEmpty())
 896→                return List.of();
 897→            DecodedNode node = decodeNode(opt.get().toArray(ValueLayout.JAVA_BYTE));
 898→            if (layer >= node.layerNeighbors().size())
 899→                return List.of();
 900→            return node.layerNeighbors().get(layer);
 901→        }
 902→
 903→        private boolean isSoftDeleted(byte[] docIdBytes) throws IOException {
 904→            return lsmTree.get(MemorySegment.ofArray(softDeleteKey(docIdBytes))).isPresent();
 905→        }
 906→
 907→        private static byte[] softDeleteKey(byte[] docIdBytes) {
 908→            byte[] key = new byte[1 + docIdBytes.length];
 909→            key[0] = SOFT_DELETE_PREFIX;
 910→            System.arraycopy(docIdBytes, 0, key, 1, docIdBytes.length);
 911→            return key;
 912→        }
 913→
 914→        // --- Node encoding/decoding ---
 915→
 916→        private record DecodedNode(List<List<byte[]>> layerNeighbors, float[] vector) {
 917→        }
 918→
 919→        private static byte[] encodeNode(byte[] docIdBytes, List<List<byte[]>> layerNeighbors,
 920→                float[] vector) {
 921→            int docIdLen = docIdBytes.length;
 922→            int layerCount = layerNeighbors.size();
 923→            int neighborBytes = layerNeighbors.stream().mapToInt(l -> 4 + l.size() * docIdLen)
 924→                    .sum();
 925→            int totalSize = 4 + 4 + neighborBytes + vector.length * 4;
 926→
 927→            byte[] buf = new byte[totalSize];
 928→            int off = 0;
 929→            off = writeInt(buf, off, docIdLen);
 930→            off = writeInt(buf, off, layerCount);
 931→            for (List<byte[]> neighbors : layerNeighbors) {
 932→                off = writeInt(buf, off, neighbors.size());
 933→                for (byte[] nb : neighbors) {
 934→                    System.arraycopy(nb, 0, buf, off, docIdLen);
 935→                    off += docIdLen;
 936→                }
 937→            }
 938→            byte[] vectorBytes = encodeFloats(vector);
 939→            System.arraycopy(vectorBytes, 0, buf, off, vectorBytes.length);
 940→            return buf;
 941→        }
 942→
 943→        private static DecodedNode decodeNode(byte[] bytes) {
 944→            int off = 0;
 945→            int docIdLen = readInt(bytes, off);
 946→            off += 4;
 947→            int layerCount = readInt(bytes, off);
 948→            off += 4;
 949→            List<List<byte[]>> layers = new ArrayList<>(layerCount);
 950→            for (int l = 0; l < layerCount; l++) {
 951→                int neighborCount = readInt(bytes, off);
 952→                off += 4;
 953→                List<byte[]> neighbors = new ArrayList<>(neighborCount);
 954→                for (int n = 0; n < neighborCount; n++) {
 955→                    neighbors.add(Arrays.copyOfRange(bytes, off, off + docIdLen));
 956→                    off += docIdLen;
 957→                }
 958→                layers.add(neighbors);
 959→            }
 960→            int vecBytes = bytes.length - off;
 961→            float[] vector = decodeFloats(Arrays.copyOfRange(bytes, off, bytes.length),
 962→                    vecBytes / 4);
 963→            return new DecodedNode(layers, vector);
 964→        }
 965→
 966→        // -----------------------------------------------------------------------
 967→        // Builder
 968→        // -----------------------------------------------------------------------
 969→
 970→        /** Builder for {@link LsmVectorIndex.Hnsw}. */
 971→        public static final class Builder<D> extends AbstractBuilder<D, Builder<D>> {
 972→
 973→            private int maxConnections = 16;
 974→            private int efConstruction = 200;
 975→            private int efSearch = 50;
 976→
 977→            public Builder<D> maxConnections(int maxConnections) {
 978→                if (maxConnections <= 0)
 979→                    throw new IllegalArgumentException("maxConnections must be > 0");
 980→                this.maxConnections = maxConnections;
 981→                return this;
 982→            }
 983→
 984→            public Builder<D> efConstruction(int ef) {
 985→                if (ef <= 0)
 986→                    throw new IllegalArgumentException("efConstruction must be > 0");
 987→                this.efConstruction = ef;
 988→                return this;
 989→            }
 990→
 991→            public Builder<D> efSearch(int ef) {
 992→                if (ef <= 0)
 993→                    throw new IllegalArgumentException("efSearch must be > 0");
 994→                this.efSearch = ef;
 995→                return this;
 996→            }
 997→
 998→            public VectorIndex.Hnsw<D> build() {
 999→                validateBase();
1000→                return new LsmVectorIndex.Hnsw<>(lsmTree, docIdSerializer, dimensions,
1001→                        similarityFunction, maxConnections, efConstruction, efSearch);
1002→            }
1003→        }
1004→    }
1005→}
