content.content:
   1→package jlsm.vector;
   2→
   3→import jdk.incubator.vector.FloatVector;
   4→import jdk.incubator.vector.VectorOperators;
   5→import jdk.incubator.vector.VectorSpecies;
   6→import jlsm.core.indexing.SimilarityFunction;
   7→import jlsm.core.indexing.VectorIndex;
   8→import jlsm.core.io.MemorySerializer;
   9→import jlsm.core.model.Entry;
  10→import jlsm.core.tree.LsmTree;
  11→import jlsm.core.tree.PrefetchHint;
  12→
  13→import java.io.IOException;
  14→import java.lang.foreign.MemorySegment;
  15→import java.lang.foreign.ValueLayout;
  16→import java.nio.ByteBuffer;
  17→import java.util.ArrayList;
  18→import java.util.Arrays;
  19→import java.util.Comparator;
  20→import java.util.HashSet;
  21→import java.util.Iterator;
  22→import java.util.List;
  23→import java.util.Objects;
  24→import java.util.Optional;
  25→import java.util.PriorityQueue;
  26→import java.util.Random;
  27→import java.util.Set;
  28→import java.util.stream.Collectors;
  29→
  30→/**
  31→ * Non-instantiable namespace class containing concrete {@link VectorIndex} implementations backed
  32→ * by an {@link LsmTree}.
  33→ *
  34→ * <ul>
  35→ * <li>{@link IvfFlat} — Inverted File with Flat re-scoring. Uses three key namespaces within one
  36→ * {@link LsmTree}: centroid coordinates {@code [0x00]}, posting-list entries {@code [0x01]}, and
  37→ * reverse-lookup entries {@code [0x02]}.</li>
  38→ * <li>{@link Hnsw} — Hierarchical Navigable Small World graph. Uses doc-id bytes as node keys,
  39→ * {@code [0xFE]} for the entry point, and {@code [0xFF][docId]} for soft-deletes.</li>
  40→ * </ul>
  41→ *
  42→ * <p>
  43→ * All similarity computations are accelerated with {@code FloatVector.SPECIES_PREFERRED} from
  44→ * {@code jdk.incubator.vector}, with a scalar tail loop for dimensions not covered by the SIMD
  45→ * width.
  46→ *
  47→ * <p>
  48→ * Obtain instances via {@link #ivfFlatBuilder()} and {@link #hnswBuilder()}.
  49→ */
  50→public final class LsmVectorIndex {
  51→
  52→    // Preferred SIMD species for float computation
  53→    private static final VectorSpecies<Float> SPECIES = FloatVector.SPECIES_PREFERRED;
  54→
  55→    private LsmVectorIndex() {
  56→        throw new UnsupportedOperationException("utility class");
  57→    }
  58→
  59→    // -----------------------------------------------------------------------
  60→    // Factory methods
  61→    // -----------------------------------------------------------------------
  62→
  63→    /** Returns a builder for an {@link IvfFlat} vector index backed by an {@link LsmTree}. */
  64→    public static <D> IvfFlat.Builder<D> ivfFlatBuilder() {
  65→        return new IvfFlat.Builder<>();
  66→    }
  67→
  68→    /** Returns a builder for an {@link Hnsw} vector index backed by an {@link LsmTree}. */
  69→    public static <D> Hnsw.Builder<D> hnswBuilder() {
  70→        return new Hnsw.Builder<>();
  71→    }
  72→
  73→    // -----------------------------------------------------------------------
  74→    // Float encoding helpers
  75→    // -----------------------------------------------------------------------
  76→
  77→    static byte[] encodeFloats(float[] floats) {
  78→        assert floats != null : "floats must not be null";
  79→        byte[] bytes = new byte[floats.length * 4];
  80→        for (int i = 0; i < floats.length; i++) {
  81→            int bits = Float.floatToRawIntBits(floats[i]);
  82→            bytes[i * 4] = (byte) (bits >>> 24);
  83→            bytes[i * 4 + 1] = (byte) (bits >>> 16);
  84→            bytes[i * 4 + 2] = (byte) (bits >>> 8);
  85→            bytes[i * 4 + 3] = (byte) bits;
  86→        }
  87→        return bytes;
  88→    }
  89→
  90→    static float[] decodeFloats(byte[] bytes, int dimensions) {
  91→        assert bytes != null : "bytes must not be null";
  92→        assert bytes.length == dimensions * 4 : "byte count mismatch";
  93→        float[] floats = new float[dimensions];
  94→        for (int i = 0; i < dimensions; i++) {
  95→            int bits = ((bytes[i * 4] & 0xFF) << 24) | ((bytes[i * 4 + 1] & 0xFF) << 16)
  96→                    | ((bytes[i * 4 + 2] & 0xFF) << 8) | (bytes[i * 4 + 3] & 0xFF);
  97→            floats[i] = Float.intBitsToFloat(bits);
  98→        }
  99→        return floats;
 100→    }
 101→
 102→    // -----------------------------------------------------------------------
 103→    // SIMD similarity functions
 104→    // -----------------------------------------------------------------------
 105→
 106→    /** Returns the dot product of two float vectors using SIMD + scalar tail. */
 107→    static float dotProduct(float[] a, float[] b) {
 108→        assert a != null && b != null : "vectors must not be null";
 109→        assert a.length == b.length : "vectors must have the same length";
 110→        int i = 0, ub = SPECIES.loopBound(a.length);
 111→        var acc = FloatVector.zero(SPECIES);
 112→        for (; i < ub; i += SPECIES.length()) {
 113→            acc = FloatVector.fromArray(SPECIES, a, i).fma(FloatVector.fromArray(SPECIES, b, i),
 114→                    acc);
 115→        }
 116→        float sum = acc.reduceLanes(VectorOperators.ADD);
 117→        for (; i < a.length; i++)
 118→            sum += a[i] * b[i];
 119→        return sum;
 120→    }
 121→
 122→    /** Returns the cosine similarity in [−1, 1]; 0 if either vector has zero norm. */
 123→    static float cosine(float[] a, float[] b) {
 124→        float dot = dotProduct(a, b);
 125→        float denom = (float) Math.sqrt(dotProduct(a, a) * dotProduct(b, b));
 126→        return denom == 0.0f ? 0.0f : dot / denom;
 127→    }
 128→
 129→    /** Returns the negated Euclidean distance ≤ 0; closer = less negative = higher score. */
 130→    static float euclidean(float[] a, float[] b) {
 131→        assert a.length == b.length : "vectors must have the same length";
 132→        int i = 0, ub = SPECIES.loopBound(a.length);
 133→        var acc = FloatVector.zero(SPECIES);
 134→        for (; i < ub; i += SPECIES.length()) {
 135→            var diff = FloatVector.fromArray(SPECIES, a, i)
 136→                    .sub(FloatVector.fromArray(SPECIES, b, i));
 137→            acc = diff.fma(diff, acc);
 138→        }
 139→        float sum = acc.reduceLanes(VectorOperators.ADD);
 140→        for (; i < a.length; i++) {
 141→            float d = a[i] - b[i];
 142→            sum += d * d;
 143→        }
 144→        return -(float) Math.sqrt(sum);
 145→    }
 146→
 147→    /** Dispatches to the appropriate similarity function; higher = more similar for all. */
 148→    static float score(float[] a, float[] b, SimilarityFunction fn) {
 149→        return switch (fn) {
 150→            case COSINE -> cosine(a, b);
 151→            case DOT_PRODUCT -> dotProduct(a, b);
 152→            case EUCLIDEAN -> euclidean(a, b);
 153→        };
 154→    }
 155→
 156→    // -----------------------------------------------------------------------
 157→    // Byte encoding helpers
 158→    // -----------------------------------------------------------------------
 159→
 160→    private static int writeInt(byte[] buf, int off, int v) {
 161→        buf[off++] = (byte) (v >>> 24);
 162→        buf[off++] = (byte) (v >>> 16);
 163→        buf[off++] = (byte) (v >>> 8);
 164→        buf[off++] = (byte) v;
 165→        return off;
 166→    }
 167→
 168→    private static int readInt(byte[] buf, int off) {
 169→        return ((buf[off] & 0xFF) << 24) | ((buf[off + 1] & 0xFF) << 16)
 170→                | ((buf[off + 2] & 0xFF) << 8) | (buf[off + 3] & 0xFF);
 171→    }
 172→
 173→    // -----------------------------------------------------------------------
 174→    // Shared result type
 175→    // -----------------------------------------------------------------------
 176→
 177→    private record ScoredCandidate(byte[] docIdBytes, float score) {
 178→    }
 179→
 180→    // -----------------------------------------------------------------------
 181→    // Abstract builder base
 182→    // -----------------------------------------------------------------------
 183→
 184→    private abstract static class AbstractBuilder<D, B extends AbstractBuilder<D, B>> {
 185→
 186→        LsmTree lsmTree;
 187→        MemorySerializer<D> docIdSerializer;
 188→        int dimensions; // 0 = not set
 189→        SimilarityFunction similarityFunction;
 190→
 191→        @SuppressWarnings("unchecked")
 192→        public B lsmTree(LsmTree lsmTree) {
 193→            this.lsmTree = Objects.requireNonNull(lsmTree, "lsmTree must not be null");
 194→            return (B) this;
 195→        }
 196→
 197→        @SuppressWarnings("unchecked")
 198→        public B docIdSerializer(MemorySerializer<D> docIdSerializer) {
 199→            this.docIdSerializer = Objects.requireNonNull(docIdSerializer,
 200→                    "docIdSerializer must not be null");
 201→            return (B) this;
 202→        }
 203→
 204→        @SuppressWarnings("unchecked")
 205→        public B dimensions(int dimensions) {
 206→            if (dimensions <= 0)
 207→                throw new IllegalArgumentException("dimensions must be > 0, got: " + dimensions);
 208→            this.dimensions = dimensions;
 209→            return (B) this;
 210→        }
 211→
 212→        @SuppressWarnings("unchecked")
 213→        public B similarityFunction(SimilarityFunction fn) {
 214→            this.similarityFunction = Objects.requireNonNull(fn,
 215→                    "similarityFunction must not be null");
 216→            return (B) this;
 217→        }
 218→
 219→        void validateBase() {
 220→            Objects.requireNonNull(lsmTree, "lsmTree must not be null");
 221→            Objects.requireNonNull(docIdSerializer, "docIdSerializer must not be null");
 222→            if (dimensions <= 0) {
 223→                throw new IllegalArgumentException("dimensions must be > 0");
 224→            }
 225→            Objects.requireNonNull(similarityFunction, "similarityFunction must not be null");
 226→        }
 227→    }
 228→
 229→    // -----------------------------------------------------------------------
 230→    // IvfFlat implementation
 231→    // -----------------------------------------------------------------------
 232→
 233→    /**
 234→     * Inverted File Flat (IVF-Flat) vector index.
 235→     *
 236→     * <h2>Key namespaces within the backing {@link LsmTree}</h2>
 237→     *
 238→     * <pre>
 239→     *   [0x00][4-byte BE centroid_id]               → dim×4 bytes (centroid float coords)
 240→     *   [0x01][4-byte BE centroid_id][doc_id_bytes] → dim×4 bytes (vector float coords)
 241→     *   [0x02][doc_id_bytes]                        → 4-byte BE centroid_id (reverse lookup)
 242→     * </pre>
 243→     *
 244→     * <h2>Clustering strategy</h2> The first {@code numClusters} indexed vectors become centroids.
 245→     * Subsequent vectors are assigned to the nearest centroid (using the configured
 246→     * {@link SimilarityFunction}).
 247→     */
 248→    public static final class IvfFlat<D> implements VectorIndex.IvfFlat<D> {
 249→
 250→        // Key namespace prefix bytes
 251→        private static final byte CENTROID_PREFIX = 0x00;
 252→        private static final byte POSTING_PREFIX = 0x01;
 253→        private static final byte REVERSE_PREFIX = 0x02;
 254→
 255→        // Scan bounds: [CENTROID_PREFIX, POSTING_PREFIX) covers all centroid keys
 256→        private static final MemorySegment CENTROID_SCAN_START = MemorySegment
 257→                .ofArray(new byte[]{ CENTROID_PREFIX });
 258→        private static final MemorySegment CENTROID_SCAN_END = MemorySegment
 259→                .ofArray(new byte[]{ POSTING_PREFIX });
 260→
 261→        private final LsmTree lsmTree;
 262→        private final MemorySerializer<D> docIdSerializer;
 263→        private final int dimensions;
 264→        private final SimilarityFunction similarityFunction;
 265→        private final int numClusters;
 266→        private final int nprobe;
 267→
 268→        private IvfFlat(LsmTree lsmTree, MemorySerializer<D> docIdSerializer, int dimensions,
 269→                SimilarityFunction similarityFunction, int numClusters, int nprobe) {
 270→            assert lsmTree != null;
 271→            assert docIdSerializer != null;
 272→            assert dimensions > 0;
 273→            assert similarityFunction != null;
 274→            assert numClusters > 0;
 275→            assert nprobe > 0;
 276→            this.lsmTree = lsmTree;
 277→            this.docIdSerializer = docIdSerializer;
 278→            this.dimensions = dimensions;
 279→            this.similarityFunction = similarityFunction;
 280→            this.numClusters = numClusters;
 281→            this.nprobe = nprobe;
 282→        }
 283→
 284→        @Override
 285→        public void index(D docId, float[] vector) throws IOException {
 286→            Objects.requireNonNull(docId, "docId must not be null");
 287→            Objects.requireNonNull(vector, "vector must not be null");
 288→            if (vector.length != dimensions) {
 289→                throw new IllegalArgumentException(
 290→                        "vector.length=" + vector.length + " != dimensions=" + dimensions);
 291→            }
 292→
 293→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
 294→            byte[] vectorBytes = encodeFloats(vector);
 295→
 296→            int centroidId = assignCentroid(vector);
 297→
 298→            // Store posting: [0x01][centroid_id][docId] → vector
 299→            lsmTree.put(MemorySegment.ofArray(postingKey(centroidId, docIdBytes)),
 300→                    MemorySegment.ofArray(vectorBytes));
 301→
 302→            // Store reverse lookup: [0x02][docId] → centroid_id (4 bytes BE)
 303→            lsmTree.put(MemorySegment.ofArray(reverseKey(docIdBytes)),
 304→                    MemorySegment.ofArray(encodeCentroidId(centroidId)));
 305→        }
 306→
 307→        @Override
 308→        public void remove(D docId) throws IOException {
 309→            Objects.requireNonNull(docId, "docId must not be null");
 310→
 311→            byte[] docIdBytes = docIdSerializer.serialize(docId).toArray(ValueLayout.JAVA_BYTE);
 312→            byte[] revKey = reverseKey(docIdBytes);
 313→
 314→            Optional<MemorySegment> revOpt = lsmTree.get(MemorySegment.ofArray(revKey));
 315→            if (revOpt.isEmpty())
 316→                return; // not indexed
 317→
 318→            int centroidId = decodeCentroidId(revOpt.get().toArray(ValueLayout.JAVA_BYTE), 0);
 319→
 320→            lsmTree.delete(MemorySegment.ofArray(postingKey(centroidId, docIdBytes)));
 321→            lsmTree.delete(MemorySegment.ofArray(revKey));
 322→        }
 323→
 324→        @Override
 325→        public List<VectorIndex.SearchResult<D>> search(float[] query, int topK)
 326→                throws IOException {
 327→            Objects.requireNonNull(query, "query must not be null");
 328→            if (query.length != dimensions) {
 329→                throw new IllegalArgumentException(
 330→                        "query.length=" + query.length + " != dimensions=" + dimensions);
 331→            }
 332→            if (topK <= 0)
 333→                throw new IllegalArgumentException("topK must be > 0");
 334→
 335→            // Load all centroids
 336→            List<float[]> centroidVecs = new ArrayList<>();
 337→            List<Integer> centroidIds = new ArrayList<>();
 338→            Iterator<Entry> centIt = lsmTree.scan(CENTROID_SCAN_START, CENTROID_SCAN_END);
 339→            while (centIt.hasNext()) {
 340→                Entry entry = centIt.next();
 341→                if (!(entry instanceof Entry.Put put))
 342→                    continue;
 343→                byte[] key = entry.key().toArray(ValueLayout.JAVA_BYTE);
 344→                if (key.length != 5 || key[0] != CENTROID_PREFIX)
 345→                    continue;
 346→                int cid = decodeCentroidId(key, 1);
 347→                float[] cVec = decodeFloats(put.value().toArray(ValueLayout.JAVA_BYTE), dimensions);
 348→                centroidVecs.add(cVec);
 349→                centroidIds.add(cid);
 350→            }
 351→
 352→            if (centroidVecs.isEmpty())
 353→                return List.of();
 354→
 355→            // Score centroids, pick top nprobe
 356→            int actualNprobe = Math.min(nprobe, centroidVecs.size());
 357→            int[] nearestCentroidIds = topNCentroids(query, centroidVecs, centroidIds,
 358→                    actualNprobe);
 359→
 360→            // Accumulate candidates from posting lists (min-heap to evict worst when over topK)
 361→            PriorityQueue<ScoredCandidate> heap = new PriorityQueue<>(
 362→                    Comparator.comparingDouble(ScoredCandidate::score)); // min at head for eviction
 363→
 364→            for (int cid : nearestCentroidIds) {
 365→                byte[] postStart = postingKey(cid, new byte[0]);
 366→                byte[] postEnd = postingEndKey(cid);
 367→
 368→                Iterator<Entry> postIt = lsmTree.scan(MemorySegment.ofArray(postStart),
 369→                        MemorySegment.ofArray(postEnd));
 370→
 371→                while (postIt.hasNext()) {
 372→                    Entry entry = postIt.next();
 373→                    if (!(entry instanceof Entry.Put put))
 374→                        continue; // skip tombstones
 375→
 376→                    byte[] key = entry.key().toArray(ValueLayout.JAVA_BYTE);
 377→                    if (key.length <= 5 || key[0] != POSTING_PREFIX)
 378→                        continue;
 379→
 380→                    byte[] docIdBytes = Arrays.copyOfRange(key, 5, key.length);
 381→                    float[] vec = decodeFloats(put.value().toArray(ValueLayout.JAVA_BYTE),
 382→                            dimensions);
 383→                    float s = score(query, vec, similarityFunction);
 384→
 385→                    heap.add(new ScoredCandidate(docIdBytes, s));
 386→                    if (heap.size() > topK)
 387→                        heap.poll(); // evict worst
 388→                }
 389→            }
 390→
 391→            // Drain heap in descending order
 392→            List<ScoredCandidate> sorted = new ArrayList<>(heap);
 393→            sorted.sort((a, b) -> Float.compare(b.score(), a.score()));
 394→
 395→            List<VectorIndex.SearchResult<D>> results = new ArrayList<>(sorted.size());
 396→            for (ScoredCandidate c : sorted) {
 397→                D id = docIdSerializer.deserialize(MemorySegment.ofArray(c.docIdBytes()));
 398→                results.add(new VectorIndex.SearchResult<>(id, c.score()));
 399→            }
 400→            return results;
 401→        }
