 403→        @Override
 404→        public void close() throws IOException {
 405→            lsmTree.close();
 406→        }
 407→
 408→        // --- Key construction helpers ---
 409→
 410→        private static byte[] centroidKey(int centroidId) {
 411→            return new byte[]{ CENTROID_PREFIX, (byte) (centroidId >>> 24),
 412→                    (byte) (centroidId >>> 16), (byte) (centroidId >>> 8), (byte) centroidId };
 413→        }
 414→
 415→        private static byte[] postingKey(int centroidId, byte[] docIdBytes) {
 416→            byte[] key = new byte[5 + docIdBytes.length];
 417→            key[0] = POSTING_PREFIX;
 418→            key[1] = (byte) (centroidId >>> 24);
 419→            key[2] = (byte) (centroidId >>> 16);
 420→            key[3] = (byte) (centroidId >>> 8);
 421→            key[4] = (byte) centroidId;
 422→            System.arraycopy(docIdBytes, 0, key, 5, docIdBytes.length);
 423→            return key;
 424→        }
 425→
 426→        private static byte[] postingEndKey(int centroidId) {
 427→            long next = (centroidId & 0xFFFFFFFFL) + 1L;
 428→            if (next > 0xFFFFFFFFL) {
 429→                return new byte[]{ REVERSE_PREFIX }; // overflow → next prefix byte
 430→            }
 431→            return new byte[]{ POSTING_PREFIX, (byte) (next >>> 24), (byte) (next >>> 16),
 432→                    (byte) (next >>> 8), (byte) next };
 433→        }
 434→
 435→        private static byte[] reverseKey(byte[] docIdBytes) {
 436→            byte[] key = new byte[1 + docIdBytes.length];
 437→            key[0] = REVERSE_PREFIX;
 438→            System.arraycopy(docIdBytes, 0, key, 1, docIdBytes.length);
 439→            return key;
 440→        }
 441→
 442→        private static byte[] encodeCentroidId(int centroidId) {
 443→            return new byte[]{ (byte) (centroidId >>> 24), (byte) (centroidId >>> 16),
 444→                    (byte) (centroidId >>> 8), (byte) centroidId };
 445→        }
 446→
 447→        private static int decodeCentroidId(byte[] bytes, int offset) {
 448→            return ((bytes[offset] & 0xFF) << 24) | ((bytes[offset + 1] & 0xFF) << 16)
 449→                    | ((bytes[offset + 2] & 0xFF) << 8) | (bytes[offset + 3] & 0xFF);
 450→        }
 451→
 452→        // --- Centroid assignment ---
 453→
 454→        /**
 455→         * Returns the centroid ID to assign to a new vector. Creates a new centroid if fewer than
 456→         * {@code numClusters} centroids exist; otherwise assigns to the most similar existing one.
 457→         */
 458→        private int assignCentroid(float[] vector) throws IOException {
 459→            List<float[]> centroids = new ArrayList<>();
 460→            List<Integer> centroidIdList = new ArrayList<>();
 461→
 462→            Iterator<Entry> it = lsmTree.scan(CENTROID_SCAN_START, CENTROID_SCAN_END);
 463→            while (it.hasNext()) {
 464→                Entry entry = it.next();
 465→                if (!(entry instanceof Entry.Put put))
 466→                    continue;
 467→                byte[] key = entry.key().toArray(ValueLayout.JAVA_BYTE);
 468→                if (key.length != 5 || key[0] != CENTROID_PREFIX)
 469→                    continue;
 470→                int cid = decodeCentroidId(key, 1);
 471→                float[] cVec = decodeFloats(put.value().toArray(ValueLayout.JAVA_BYTE), dimensions);
 472→                centroids.add(cVec);
 473→                centroidIdList.add(cid);
 474→            }
 475→
 476→            if (centroids.size() < numClusters) {
 477→                int newCid = centroids.size(); // sequential 0-based centroid IDs
 478→                lsmTree.put(MemorySegment.ofArray(centroidKey(newCid)),
 479→                        MemorySegment.ofArray(encodeFloats(vector)));
 480→                return newCid;
 481→            }
 482→
 483→            return nearestCentroid(vector, centroids, centroidIdList);
 484→        }
 485→
 486→        private int nearestCentroid(float[] vector, List<float[]> centroids, List<Integer> ids) {
 487→            int best = ids.get(0);
 488→            float bestScore = score(vector, centroids.get(0), similarityFunction);
 489→            for (int i = 1; i < centroids.size(); i++) {
 490→                float s = score(vector, centroids.get(i), similarityFunction);
 491→                if (s > bestScore) {
 492→                    bestScore = s;
 493→                    best = ids.get(i);
 494→                }
 495→            }
 496→            return best;
 497→        }
 498→
 499→        private int[] topNCentroids(float[] query, List<float[]> centroids, List<Integer> ids,
 500→                int n) {
 501→            float[] scores = new float[centroids.size()];
 502→            for (int i = 0; i < centroids.size(); i++) {
 503→                scores[i] = score(query, centroids.get(i), similarityFunction);
 504→            }
 505→            Integer[] indices = new Integer[centroids.size()];
 506→            for (int i = 0; i < indices.length; i++)
 507→                indices[i] = i;
 508→            Arrays.sort(indices, (a, b) -> Float.compare(scores[b], scores[a])); // descending
 509→
 510→            int[] result = new int[n];
 511→            for (int i = 0; i < n; i++)
 512→                result[i] = ids.get(indices[i]);
 513→            return result;
 514→        }
